INSERT INTO src_locator(source_work_id,source_artifact_id,locator_type,heading_path,display_citation) SELECT artifact.source_work_id,artifact.source_artifact_id,'heading','Environments and Hazards > Suffocation',CASE work.work_code WHEN 'cepheus-engine.ogn' THEN 'Cepheus Engine SRD, Environments and Hazards: Suffocation' ELSE 'Cepheus Engine v9.1, Environments and Hazards: Suffocation' END FROM src_artifact artifact JOIN src_work work USING(source_work_id) WHERE artifact.source_uri IN('src/book3/environments-and-hazards.md','https://cepheus-srd.opengamingnetwork.com/cepheus-engine-srd/cepheus-engine-environments-and-hazards/') ON CONFLICT DO NOTHING;
WITH package AS(SELECT content_package_id FROM sys_content_package WHERE package_code='cepheus-engine') INSERT INTO rule_rule(content_package_id,rule_code,name,rule_category,rule_status,description) SELECT content_package_id,'environment.suffocation','Suffocation','other','approved','Insufficient oxygen deals 1D6 damage each minute; utterly airless exposure deals 1D6 each personal-combat round.' FROM package;
CREATE TABLE rule_suffocation_profile(suffocation_profile_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,rule_id bigint NOT NULL REFERENCES rule_rule(rule_id),exposure_code text NOT NULL UNIQUE,name text NOT NULL,damage_dice_count smallint NOT NULL CHECK(damage_dice_count=1),damage_die_sides smallint NOT NULL CHECK(damage_die_sides=6),interval_kind text NOT NULL CHECK(interval_kind IN('minute','personal-combat-round')),interval_quantity smallint NOT NULL CHECK(interval_quantity=1));
INSERT INTO rule_suffocation_profile(rule_id,exposure_code,name,damage_dice_count,damage_die_sides,interval_kind,interval_quantity) SELECT rule.rule_id,value.* FROM rule_rule rule CROSS JOIN(VALUES('limited-oxygen','Insufficient oxygen',1,6,'minute',1),('utterly-airless','Utterly without air',1,6,'personal-combat-round',1))value(exposure_code,name,damage_dice_count,damage_die_sides,interval_kind,interval_quantity) WHERE rule.rule_code='environment.suffocation';
INSERT INTO src_record_provenance(rule_id,content_package_id,source_locator_id,provenance_class,is_primary_citation) SELECT rule.rule_id,rule.content_package_id,locator.source_locator_id,CASE work.work_code WHEN 'cepheus-engine.ogn' THEN 'direct' ELSE 'corroborating' END,work.work_code='cepheus-engine.ogn' FROM rule_rule rule CROSS JOIN src_locator locator JOIN src_work work USING(source_work_id) WHERE rule.rule_code='environment.suffocation' AND locator.heading_path='Environments and Hazards > Suffocation' AND work.work_code IN('cepheus-engine.ogn','cepheus-engine.github-v9.1');
CREATE TABLE env_suffocation_episode(suffocation_episode_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,public_id uuid NOT NULL DEFAULT gen_random_uuid() UNIQUE,actor_id bigint NOT NULL,campaign_id bigint NOT NULL,suffocation_profile_id bigint NOT NULL REFERENCES rule_suffocation_profile(suffocation_profile_id),encounter_id bigint REFERENCES enc_personal_combat(encounter_id),began_campaign_day bigint,began_campaign_second integer CHECK(began_campaign_second BETWEEN 0 AND 86399),began_combat_round integer CHECK(began_combat_round>0),episode_status text NOT NULL DEFAULT 'active' CHECK(episode_status IN('active','air-restored')),ticks_completed integer NOT NULL DEFAULT 0 CHECK(ticks_completed>=0),last_campaign_total_seconds bigint,last_combat_round integer,concurrency_version bigint NOT NULL DEFAULT 1 CHECK(concurrency_version>0),opened_at timestamptz NOT NULL DEFAULT clock_timestamp(),resolved_at timestamptz,FOREIGN KEY(actor_id,campaign_id) REFERENCES actor_actor(actor_id,campaign_id),CHECK((episode_status='active')=(resolved_at IS NULL)),CHECK((encounter_id IS NULL AND began_campaign_day IS NOT NULL AND began_campaign_second IS NOT NULL AND began_combat_round IS NULL) OR (encounter_id IS NOT NULL AND began_campaign_day IS NULL AND began_campaign_second IS NULL AND began_combat_round IS NOT NULL)));
CREATE UNIQUE INDEX env_one_active_suffocation_episode ON env_suffocation_episode(actor_id) WHERE episode_status='active';
CREATE FUNCTION env_validate_suffocation_episode() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE kind text;BEGIN SELECT interval_kind INTO STRICT kind FROM rule_suffocation_profile WHERE suffocation_profile_id=NEW.suffocation_profile_id;IF (kind='minute')<>(NEW.encounter_id IS NULL) THEN RAISE EXCEPTION 'Suffocation episode timing mode must match its published profile' USING ERRCODE='23514';END IF;RETURN NEW;END $$;
CREATE TRIGGER env_suffocation_episode_valid BEFORE INSERT ON env_suffocation_episode FOR EACH ROW EXECUTE FUNCTION env_validate_suffocation_episode();
CREATE TABLE env_suffocation_tick_receipt(suffocation_tick_receipt_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,public_id uuid NOT NULL DEFAULT gen_random_uuid() UNIQUE,suffocation_episode_id bigint NOT NULL REFERENCES env_suffocation_episode(suffocation_episode_id),tick_sequence integer NOT NULL CHECK(tick_sequence>0),campaign_day bigint,campaign_second integer CHECK(campaign_second BETWEEN 0 AND 86399),combat_round integer CHECK(combat_round>0),damage_die_result smallint NOT NULL CHECK(damage_die_result BETWEEN 1 AND 6),rolled_damage smallint NOT NULL CHECK(rolled_damage=damage_die_result),episode_version_before bigint NOT NULL,episode_version_after bigint NOT NULL CHECK(episode_version_after=episode_version_before+1),recorded_at timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(suffocation_episode_id,tick_sequence),CHECK((campaign_day IS NOT NULL AND campaign_second IS NOT NULL AND combat_round IS NULL) OR (campaign_day IS NULL AND campaign_second IS NULL AND combat_round IS NOT NULL)));
CREATE TABLE env_suffocation_relief_receipt(suffocation_relief_receipt_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,suffocation_episode_id bigint NOT NULL UNIQUE REFERENCES env_suffocation_episode(suffocation_episode_id),episode_version_before bigint NOT NULL,episode_version_after bigint NOT NULL CHECK(episode_version_after=episode_version_before+1),recorded_at timestamptz NOT NULL DEFAULT clock_timestamp());
ALTER TABLE health_damage_instance ADD COLUMN suffocation_tick_receipt_id bigint UNIQUE REFERENCES env_suffocation_tick_receipt(suffocation_tick_receipt_id) DEFERRABLE INITIALLY DEFERRED;ALTER TABLE health_damage_instance DROP CONSTRAINT health_damage_exactly_one_source_check,ADD CONSTRAINT health_damage_exactly_one_source_check CHECK(num_nonnulls(attack_command_id,environmental_command_id,explosion_command_id,grapple_option_command_id,personal_scale_attack_receipt_id,acid_damage_attempt_id,acid_fume_task_command_id,temperature_damage_receipt_id,fire_resolution_receipt_id,fall_attempt_id,poison_attempt_id,radiation_sickness_check_receipt_id,deprivation_check_receipt_id,suffocation_tick_receipt_id)+CASE WHEN crew_damage_location_hit_receipt_id IS NULL THEN 0 ELSE 1 END+CASE WHEN missile_crew_hit_receipt_id IS NULL THEN 0 ELSE 1 END=1);
CREATE FUNCTION env_finalize_suffocation_tick() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE episode env_suffocation_episode%ROWTYPE;profile rule_suffocation_profile%ROWTYPE;total bigint;BEGIN SELECT * INTO STRICT episode FROM env_suffocation_episode WHERE suffocation_episode_id=NEW.suffocation_episode_id FOR UPDATE;SELECT * INTO STRICT profile FROM rule_suffocation_profile WHERE suffocation_profile_id=episode.suffocation_profile_id;IF episode.episode_status<>'active' OR NEW.tick_sequence<>episode.ticks_completed+1 OR NEW.episode_version_before<>episode.concurrency_version THEN RAISE EXCEPTION 'Suffocation tick must match active episode sequence and version' USING ERRCODE='23514';END IF;
 IF profile.interval_kind='minute' THEN total:=NEW.campaign_day*86400+NEW.campaign_second;IF NEW.combat_round IS NOT NULL OR total<episode.began_campaign_day*86400+episode.began_campaign_second+60 OR (episode.last_campaign_total_seconds IS NOT NULL AND total<episode.last_campaign_total_seconds+60) THEN RAISE EXCEPTION 'Limited-oxygen damage occurs once each elapsed minute' USING ERRCODE='23514';END IF;
 ELSE IF NEW.campaign_day IS NOT NULL OR episode.encounter_id IS NULL OR NEW.combat_round<episode.began_combat_round OR NEW.combat_round<>(SELECT current_round FROM enc_personal_combat WHERE encounter_id=episode.encounter_id) OR (episode.last_combat_round IS NOT NULL AND NEW.combat_round<=episode.last_combat_round) THEN RAISE EXCEPTION 'Airless damage requires the next current personal-combat round' USING ERRCODE='23514';END IF;END IF;
 INSERT INTO health_damage_instance(target_actor_id,penetrating_damage,suffocation_tick_receipt_id) VALUES(episode.actor_id,NEW.rolled_damage,NEW.suffocation_tick_receipt_id);UPDATE env_suffocation_episode SET ticks_completed=NEW.tick_sequence,last_campaign_total_seconds=CASE WHEN profile.interval_kind='minute' THEN total ELSE last_campaign_total_seconds END,last_combat_round=CASE WHEN profile.interval_kind='personal-combat-round' THEN NEW.combat_round ELSE last_combat_round END,concurrency_version=NEW.episode_version_after WHERE suffocation_episode_id=episode.suffocation_episode_id;RETURN NEW;END $$;
CREATE TRIGGER env_suffocation_tick_final BEFORE INSERT ON env_suffocation_tick_receipt FOR EACH ROW EXECUTE FUNCTION env_finalize_suffocation_tick();
CREATE FUNCTION env_finalize_suffocation_relief() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE episode env_suffocation_episode%ROWTYPE;BEGIN SELECT * INTO STRICT episode FROM env_suffocation_episode WHERE suffocation_episode_id=NEW.suffocation_episode_id FOR UPDATE;IF episode.episode_status<>'active' OR NEW.episode_version_before<>episode.concurrency_version THEN RAISE EXCEPTION 'Air restoration must match active suffocation episode version' USING ERRCODE='23514';END IF;UPDATE env_suffocation_episode SET episode_status='air-restored',resolved_at=NEW.recorded_at,concurrency_version=NEW.episode_version_after WHERE suffocation_episode_id=episode.suffocation_episode_id;RETURN NEW;END $$;
CREATE TRIGGER env_suffocation_relief_final BEFORE INSERT ON env_suffocation_relief_receipt FOR EACH ROW EXECUTE FUNCTION env_finalize_suffocation_relief();
CREATE FUNCTION env_reject_suffocation_mutation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Suffocation tick and relief history is immutable';END $$;CREATE TRIGGER env_suffocation_tick_immutable BEFORE UPDATE OR DELETE ON env_suffocation_tick_receipt FOR EACH ROW EXECUTE FUNCTION env_reject_suffocation_mutation();CREATE TRIGGER env_suffocation_relief_immutable BEFORE UPDATE OR DELETE ON env_suffocation_relief_receipt FOR EACH ROW EXECUTE FUNCTION env_reject_suffocation_mutation();CREATE FUNCTION env_guard_suffocation_state() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF pg_trigger_depth()<2 THEN RAISE EXCEPTION 'Suffocation state changes require immutable tick or relief receipts' USING ERRCODE='23514';END IF;RETURN NEW;END $$;CREATE TRIGGER env_suffocation_episode_guard BEFORE UPDATE OR DELETE ON env_suffocation_episode FOR EACH ROW EXECUTE FUNCTION env_guard_suffocation_state();
